export default {
  fetch(request) {
    const pathname = new URL(request.url).pathname;
    if (pathname === '/walkthrough.mp4') {
      if (!['GET', 'HEAD'].includes(request.method)) return new Response(null, {status:405,headers:{Allow:'GET, HEAD'}});
      const bytes = Uint8Array.from(atob(videoBase64), c => c.charCodeAt(0));
      const headers = {'Content-Type':'video/mp4','Accept-Ranges':'bytes','Cache-Control':'public, max-age=3600','Access-Control-Allow-Origin':'*','X-Content-Type-Options':'nosniff'};
      const range = request.headers.get('Range');
      if (range && request.method === 'GET') {
        const m = /^bytes=(\d*)-(\d*)$/.exec(range);
        let start=m && m[1] ? Number(m[1]) : m && m[2] ? Math.max(0,bytes.length-Number(m[2])) : NaN;
        let end=m && m[1] && m[2] ? Math.min(Number(m[2]),bytes.length-1) : bytes.length-1;
        if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end) || start>end || start>=bytes.length) return new Response(null,{status:416,headers:{...headers,'Content-Range':`bytes */${bytes.length}`}});
        const body=bytes.slice(start,end+1);
        return new Response(body,{status:206,headers:{...headers,'Content-Range':`bytes ${start}-${end}/${bytes.length}`,'Content-Length':String(body.length)}});
      }
      return new Response(request.method==='HEAD'?null:bytes,{headers:{...headers,'Content-Length':String(bytes.length)}});
    }

    if (Object.hasOwn(pages, pathname) && ['GET', 'HEAD'].includes(request.method)) {
      return new Response(request.method === 'HEAD' ? null : pages[pathname], { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=300', 'X-Content-Type-Options': 'nosniff', 'Content-Security-Policy': "default-src 'none'; font-src https://www.questportal.com; media-src 'self'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'", 'Referrer-Policy': 'no-referrer' } });
    }
    if (pathname !== challengePath) {
      return new Response('Not found', { status: 404 });
    }
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return new Response('Method not allowed', {
        status: 405,
        headers: { Allow: 'GET, HEAD' },
      });
    }
    return new Response(request.method === 'HEAD' ? null : challenge, {
      headers: {
        'Content-Type': 'text/plain; charset=utf-8',
        'Cache-Control': 'no-store',
        'X-Content-Type-Options': 'nosniff',
      },
    });
  },
};

